      { l: 1, q: "Instead of the photo, the page shows this. What's the most likely cause?", a: "The image's file path is wrong", w: ["The alt text is too short", "The CSS file is missing", "The page needs a viewport tag"], why: "The browser couldn't find the file, so it shows the alt text instead. Check the folder, the spelling and the capital letters.", media: { type: "svg", svg: SVG_BROKENIMG } },
      { l: 2, q: "Which part of the CSS box model is the arrow pointing at?", a: "Margin", w: ["Padding", "Border", "Content"], why: "From the inside out: content, padding, border, margin. Margin is the space outside the border.", media: { type: "svg", svg: SVG_BOXMODEL } },
      { l: 3, q: "Which flexbox rule spreads three boxes out like this?", a: "justify-content: space-between", w: ["justify-content: center", "align-items: stretch", "flex-wrap: wrap"], why: "space-between pushes the first and last items to the edges and shares the leftover space between them.", media: { type: "svg", svg: SVG_SPACEBETWEEN } },
      { l: 4, q: "This page's CSS is responsive, but a phone still shows it shrunk down like this. What's missing from its <head>?", a: "The viewport meta tag", w: ["A favicon", "A <title>", "The charset meta tag"], why: "Without <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">, phones pretend to be a wide desktop screen and shrink the page.", media: { type: "svg", svg: SVG_NOVIEWPORT } }
